<?php
session_start();
require_once 'core/db.php';
require_once 'core/functions.php';

// Telegram Mini-App ONLY mode is always enforced.
$tg_only_mode = '1';

if (!isset($_GET['tg'])) {
    include 'pages/landing_tg.php';
    exit();
}

if (!isset($_SESSION['user_id']) && isset($_COOKIE['remember_browser'])) {
    $userId = (int)$_COOKIE['remember_browser'];
    if ($userId > 0) {
        $stmt = $pdo->prepare("SELECT id, is_banned FROM users WHERE id = ?");
        $stmt->execute([$userId]);
        $remUser = $stmt->fetch();
        if ($remUser && !$remUser['is_banned']) {
            $_SESSION['user_id'] = $userId;
            $_SESSION['login_ip'] = getUserIP();
        } elseif ($remUser && $remUser['is_banned']) {
            setcookie('remember_browser', '', time() - 3600, '/');
        }
    }
}

if (isset($_GET['logout'])) {
    setcookie('remember_browser', '', time() - 3600, '/');
    session_destroy();
    header("Location: index.php");
    exit();
}
$isLoggedIn = isset($_SESSION['user_id']);
$user = null;
if (isset($_GET['ref']) && !$isLoggedIn) {
    $_SESSION['ref'] = (int)$_GET['ref'];
}
if ($isLoggedIn) {
    $stmt = $pdo->prepare("SELECT * FROM users WHERE id = ?");
    $stmt->execute([$_SESSION['user_id']]);
    $user = $stmt->fetch();
    if (!$user || $user['is_banned']) {
        setcookie('remember_browser', '', time() - 3600, '/');
        session_destroy();
        $isLoggedIn = false;
        $user = null;
    }
}
$site_name = getSetting('site_name') ?: 'Telegram Mini-App';
$site_logo = getSetting('site_logo');
$currency_name = getSetting('currency_name') ?: 'Coins';
$gateway = 'faucetpay';
$tg_bot_url = getSetting('telegram_bot_username');
$tg_bot_app = getSetting('telegram_app_shortname');
$inputLabel = "FAUCETPAY EMAIL ADDRESS";
$inputPlaceholder = "Enter your FaucetPay EMAIL";
$inputIcon = "fas fa-wallet";
$inputHelper = "Your earnings will be sent directly to this address.";
$loginError = '';
if (isset($_SESSION['login_error'])) {
    $loginError = $_SESSION['login_error'];
    unset($_SESSION['login_error']); 
}
$statUsers = $pdo->query("SELECT COUNT(*) FROM users")->fetchColumn() ?: 0;
$statClaims = $pdo->query("SELECT COUNT(*) FROM completed_offers WHERE reward > 0")->fetchColumn() ?: 0;
$totalCoinsPaid = $pdo->query("SELECT ABS(SUM(reward)) FROM completed_offers WHERE reward < 0")->fetchColumn() ?: 0;
$exchangeRate = (float)(getSetting('exchange_rate') ?: 1000);
if ($exchangeRate > 0) {
    $statPaid = $totalCoinsPaid / $exchangeRate;
} else {
    $statPaid = 0;
}
$extraMenus = [];
try {
    if ($pdo->query("SHOW TABLES LIKE 'installed_addons'")->rowCount() > 0) {
        $installedAddons = $pdo->query("SELECT * FROM installed_addons ORDER BY id ASC")->fetchAll(PDO::FETCH_ASSOC);
        foreach ($installedAddons as $addon) {
            $isActive = true;
            $userUrl = 'addons/' . $addon['addon_id'] . '.php';
            if ($addon['addon_id'] === 'wheel_of_fortune') {
                $isActive = (getSetting('wheel_status') === '1');
                $userUrl = 'addons/wheel.php';
            }
            if ($isActive) {
                $extraMenus[] = [
                    'name' => $addon['name'],
                    'icon' => $addon['icon'],
                    'url'  => $userUrl
                ];
            }
        }
    }
} catch (Exception $e) {}
?>
