    <script>
        const themeToggleDarkIcon = document.getElementById('theme-toggle-dark-icon');
        const themeToggleLightIcon = document.getElementById('theme-toggle-light-icon');
        const themeToggleBtn = document.getElementById('theme-toggle');
        if (document.documentElement.classList.contains('dark')) {
            themeToggleLightIcon.classList.remove('hidden');
        } else {
            themeToggleDarkIcon.classList.remove('hidden');
        }
        themeToggleBtn.addEventListener('click', function() {
            themeToggleDarkIcon.classList.toggle('hidden');
            themeToggleLightIcon.classList.toggle('hidden');
            if (document.documentElement.classList.contains('dark')) {
                document.documentElement.classList.remove('dark');
                localStorage.setItem('color-theme', 'light');
            } else {
                document.documentElement.classList.add('dark');
                localStorage.setItem('color-theme', 'dark');
            }
        });
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebar-overlay');
        const mobileMenuBtn = document.getElementById('mobile-menu-btn');
        const closeSidebarBtn = document.getElementById('close-sidebar-btn');
        function toggleSidebar() {
            sidebar.classList.toggle('-translate-x-full');
            if (sidebar.classList.contains('-translate-x-full')) {
                overlay.classList.remove('opacity-100');
                setTimeout(() => overlay.classList.add('hidden'), 300);
            } else {
                overlay.classList.remove('hidden');
                setTimeout(() => overlay.classList.add('opacity-100'), 10);
            }
        }
        if (mobileMenuBtn) mobileMenuBtn.addEventListener('click', toggleSidebar);
        if (closeSidebarBtn) closeSidebarBtn.addEventListener('click', toggleSidebar);
        if (overlay) overlay.addEventListener('click', toggleSidebar);
        <?php if($isLoggedIn): ?>
        function loadContent(url, btnElement = null) {
            if (window.innerWidth < 768 && !sidebar.classList.contains('-translate-x-full')) {
                toggleSidebar();
            }
            sessionStorage.setItem('current_menu_url', url);
            document.querySelectorAll('.nav-link').forEach(el => el.classList.remove('active'));
            if(btnElement) {
                btnElement.classList.add('active');
            } else {
                document.querySelectorAll('.nav-link').forEach(el => {
                    const onclickAttr = el.getAttribute('onclick') || '';
                    if(onclickAttr.includes(url)) {
                        el.classList.add('active');
                    }
                });
            }
            const contentDiv = document.getElementById('app-content');
            contentDiv.innerHTML = `
                <div class="flex flex-col items-center justify-center min-h-[400px]">
                    <div class="w-16 h-16 border-4 border-gray-200 dark:border-white/10 border-t-brand-primary rounded-full animate-spin mb-4"></div>
                    <p class="text-gray-500 dark:text-gray-400 font-bold animate-pulse">Loading data...</p>
                </div>
            `;
            fetch(url)
                .then(response => {
                    if (!response.ok) throw new Error('Network response error');
                    return response.text();
                })
                .then(html => {
                    contentDiv.innerHTML = html;
                    const scripts = contentDiv.getElementsByTagName('script');
                    for (let i = 0; i < scripts.length; i++) {
                        eval(scripts[i].innerText);
                    }
                })
                .catch(error => {
                    contentDiv.innerHTML = `
                        <div class="bg-red-50 dark:bg-red-500/10 p-6 rounded-2xl border border-red-200 dark:border-red-500/20 text-center">
                            <i class="fas fa-triangle-exclamation text-4xl text-red-500 mb-4"></i>
                            <h3 class="text-lg font-bold text-red-600 dark:text-red-400">Failed to load content</h3>
                            <p class="text-sm text-red-500/80 mt-1">${error.message}</p>
                        </div>
                    `;
                });
        }
        window.addEventListener('DOMContentLoaded', () => {
            const lastMenu = sessionStorage.getItem('current_menu_url') || 'pages/load_dashboard.php';
            loadContent(lastMenu);
        });
        function copyRefLink() {
            var input = document.getElementById('refLinkInput');
            var btn = document.getElementById('copyBtn');
            var icon = document.getElementById('copyIcon');
            var text = document.getElementById('copyText');
            var linkValue = input.value;
            var copied = false;
            try {
                var ta = document.createElement('textarea');
                ta.value = linkValue;
                ta.style.position = 'fixed';
                ta.style.left = '-9999px';
                ta.style.top = '-9999px';
                ta.style.opacity = '0';
                document.body.appendChild(ta);
                ta.focus();
                ta.select();
                copied = document.execCommand('copy');
                document.body.removeChild(ta);
            } catch(e) {
                copied = false;
            }
            if (!copied && navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(linkValue).catch(function(){});
                copied = true;
            }
            if (copied) {
                icon.className = 'fas fa-check';
                text.textContent = 'Copied!';
                btn.classList.add('bg-emerald-500', 'text-white');
                btn.classList.remove('bg-white', 'text-violet-600');
                setTimeout(function() {
                    icon.className = 'fas fa-copy';
                    text.textContent = 'Copy Link';
                    btn.classList.remove('bg-emerald-500', 'text-white');
                    btn.classList.add('bg-white', 'text-violet-600');
                }, 2000);
            } else {
                input.focus();
                input.select();
                text.textContent = 'Press Ctrl+C';
                setTimeout(function() {
                    text.textContent = 'Copy Link';
                }, 3000);
            }
        }
        <?php endif; ?>

        function switchTab(tabName) {
            document.querySelectorAll('.tab-panel').forEach(panel => {
                panel.classList.add('hidden');
            });
            
            document.querySelectorAll('.tab-button').forEach(btn => {
                btn.classList.remove('active', 'border-brand-primary', 'text-brand-primary');
                btn.classList.add('text-gray-500', 'dark:text-gray-400', 'border-transparent');
            });
            
            document.getElementById('panel-' + tabName).classList.remove('hidden');
            
            document.getElementById('tab-' + tabName).classList.add('active', 'border-brand-primary', 'text-brand-primary');
            document.getElementById('tab-' + tabName).classList.remove('text-gray-500', 'dark:text-gray-400', 'border-transparent');
            
            if (tabName === 'history') {
                loadWithdrawalHistory(1);
            }
        }

        function loadWithdrawalHistory(page = 1) {
            const container = document.getElementById('withdrawal-history-container');
            container.innerHTML = '<div class="flex justify-center py-8"><div class="animate-spin rounded-full h-8 w-8 border-b-2 border-brand-primary"></div></div>';
            
            fetch('actions/get_withdrawal_history.php?page=' + page)
                .then(response => response.text())
                .then(html => {
                    container.innerHTML = html;
                })
                .catch(error => {
                    container.innerHTML = '<div class="text-center text-red-500 py-8"><i class="fas fa-exclamation-triangle mr-2"></i> Error loading withdrawal history</div>';
                });
        }
    </script>
    <style>
        @keyframes fadeInUp {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
    </style>
